bounded_host_request.command:
set -eu
docker exec -i deploy-postgres-1 sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB"' <<'SQL'
BEGIN;
DO $$
BEGIN
IF (SELECT count(*) FROM posting_topics
 WHERE board_key='video_chat' AND chat_id=-1002373696859 AND message_thread_id=1695
 AND purpose='announcement' AND title ILIKE '%稼げる有料動画投稿%'
 AND enabled=TRUE AND verified_by IS NOT NULL AND verified_at IS NOT NULL)<>1
THEN RAISE EXCEPTION 'EXISTING_TOPIC_IDENTITY_INVALID'; END IF;
IF EXISTS(SELECT 1 FROM posting_topics WHERE purpose='video_sale'
 AND (chat_id<>-1002373696859 OR message_thread_id<>1695))
THEN RAISE EXCEPTION 'VIDEO_SALE_CONFLICT'; END IF;
END $$;
ALTER TABLE posting_topics DROP CONSTRAINT IF EXISTS posting_topics_purpose_check;
ALTER TABLE posting_topics ADD CONSTRAINT posting_topics_purpose_check
 CHECK (purpose IN ('profile','room','announcement','link','video_sale'));
ALTER TABLE posting_topics DROP CONSTRAINT IF EXISTS posting_topics_video_sale_board_check;
ALTER TABLE posting_topics ADD CONSTRAINT posting_topics_video_sale_board_check
 CHECK (purpose <> 'video_sale' OR board_key='video_chat');
INSERT INTO posting_topics(board_key,purpose,chat_id,message_thread_id,title,verified_by,verified_at,enabled)
 SELECT board_key,'video_sale',chat_id,message_thread_id,title,verified_by,verified_at,TRUE
 FROM posting_topics
 WHERE board_key='video_chat' AND chat_id=-1002373696859
 AND message_thread_id=1695 AND purpose='announcement'
 AND title ILIKE '%稼げる有料動画投稿%' AND enabled=TRUE AND verified_by IS NOT NULL
 ON CONFLICT (board_key,purpose,chat_id,message_thread_id) DO NOTHING;
DO $$
BEGIN
IF (SELECT count(*) FROM posting_topics WHERE purpose='video_sale' AND enabled
 AND board_key='video_chat' AND chat_id=-1002373696859 AND message_thread_id=1695
 AND verified_by IS NOT NULL AND verified_at IS NOT NULL) <> 1
THEN RAISE EXCEPTION 'VIDEO_SALE_BIND_NOT_COMMITTED';END IF;
END $$;
COMMIT;
SELECT 'VIDEO_SALE_ROUTE_COUNT='||count(*) FROM posting_topics WHERE purpose='video_sale' AND enabled=TRUE;
SQL
